import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceCubeRelationDelta {
 static final String P="local/lito381/server/",N=P+"NativeSourceCubeRelation";
 static final List<String>ENGINES=List.of(P+"BattleCubeIgnitionEffects",P+"BattleCubeQuakeEffects",P+"BattleCubeShockEffects",P+"BattleCubeHarmonyEffects"),OWNERS=ENGINES;
 static void need(boolean v,String why){if(!v)throw new AssertionError(why);}
 static void remove(MethodNode m,AbstractInsnNode node,int prior,int after){var first=node;for(int i=0;i<prior;i++)first=FreezeAcceptedMethods.prev(first);var last=node;for(int i=0;i<after;i++)last=FreezeSourceTargetDelta.next(last);var stop=last.getNext();for(var n=first;n!=stop;){var next=n.getNext();m.instructions.remove(n);n=next;}}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){names.add(e.getName());var n=jar.getJarEntry(e.getName());need(n!=null,"retain original archive entries");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(n).readAllBytes()))changed.add(e.getName());}need(changed.equals(new HashSet<>(OWNERS.stream().map(x->x+".class").toList())),"four actual cube scan owners only");int count=0,compare=0,relation=0;
  for(String owner:OWNERS){var before=FreezeSourceTargetDelta.read(base,owner);var after=FreezeSourceTargetDelta.read(jar,owner);need(after.fields.size()==before.fields.size(),"no new original fields");for(int k=0;k<before.fields.size();k++){var x=before.fields.get(k);var y=after.fields.get(k);need(x.name.equals(y.name)&&x.desc.equals(y.desc)&&x.access==y.access&&Objects.equals(x.value,y.value),"original fields unchanged");}
   for(var old:before.methods){var now=after.methods.stream().filter(m->m.name.equals(old.name)&&m.desc.equals(old.desc)).findFirst().orElseThrow();for(var node:now.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N))switch(call.name){
    case "compare"->{need(old.name.equals("advance"),"original self comparison only");var field=FreezeAcceptedMethods.prev(call);var load=FreezeAcceptedMethods.prev(field);need(field instanceof FieldInsnNode f&&f.getOpcode()==GETFIELD&&f.owner.equals(owner+"$CubeLease")&&f.name.equals("cube")&&load instanceof VarInsnNode,"actual original cube local");var id=FreezeAcceptedMethods.prev(load);need(id instanceof MethodInsnNode c&&c.owner.equals(owner+"$Cube")&&c.name.equals("casterObjectId"),"original compared caster id");now.instructions.remove(load);now.instructions.remove(field);now.instructions.set(call,new InsnNode(LCMP));compare++;}
    case "relation"->{need(old.name.equals("advance")&&call.desc.equals("(L"+owner+"$Alliance;JJLjava/lang/Object;Ljava/lang/Object;)L"+owner+"$Relation;"),"typed original alliance relation");var actor=FreezeAcceptedMethods.prev(call);var field=FreezeAcceptedMethods.prev(actor);var cubeLoad=FreezeAcceptedMethods.prev(field);need(actor instanceof VarInsnNode al&&field instanceof FieldInsnNode f&&f.owner.equals(owner+"$CubeLease")&&f.name.equals("cube")&&cubeLoad instanceof VarInsnNode cl,"actual frozen actor and cube operands");var actorId=FreezeAcceptedMethods.prev(cubeLoad);var actorOriginal=FreezeAcceptedMethods.prev(actorId);var casterId=FreezeAcceptedMethods.prev(actorOriginal);var oldField=FreezeAcceptedMethods.prev(casterId);var oldCube=FreezeAcceptedMethods.prev(oldField);need(actorId instanceof MethodInsnNode ai&&ai.owner.equals(owner+"$Actor")&&ai.name.equals("objectId")&&actorOriginal instanceof VarInsnNode ao&&ao.var==((VarInsnNode)actor).var&&oldCube instanceof VarInsnNode co&&co.var==((VarInsnNode)cubeLoad).var,"same actual original decision locals");now.instructions.remove(actor);now.instructions.remove(field);now.instructions.remove(cubeLoad);call.setOpcode(INVOKEINTERFACE);call.owner=owner+"$Alliance";call.desc="(JJ)L"+owner+"$Relation;";call.itf=true;relation++;}
    default->throw new AssertionError("unreviewed Source relation port");
   }need(Arrays.equals(FreezeSourceTargetDelta.body(before,old,old.name,old.access),FreezeSourceTargetDelta.body(after,now,old.name,old.access)),"independent original inverse "+owner+old.name);count++;}need(after.methods.size()==before.methods.size(),"no new methods on actual engine or cube");
  }
  var binding=FreezeSourceTargetDelta.read(base,P+"NativePlayerCommit$Binding");var capture=binding.methods.stream().filter(m->m.name.equals("capture")).findFirst().orElseThrow();var reads=new ArrayList<String>();for(var n:capture.instructions)if(n instanceof MethodInsnNode call&&call.owner.equals(P+"ClientSession")&&Set.of("sourceCharacterIdentity","sourceAccountIdentity","selectedCharacterName").contains(call.name))reads.add(call.name);need(reads.equals(List.of("sourceCharacterIdentity","sourceAccountIdentity","selectedCharacterName")),"actual original Binding source is already a qualified character identity");var source=binding.methods.stream().filter(m->m.name.equals("source")&&m.desc.equals("()Ljava/lang/String;")).findFirst().orElseThrow();need(Arrays.stream(source.instructions.toArray()).anyMatch(n->n instanceof FieldInsnNode f&&f.getOpcode()==GETFIELD&&f.name.equals("source")&&f.desc.equals("Ljava/lang/String;")),"actual immutable source accessor");
  need(compare==4&&relation==4,"four actual original self/alliance ports");var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName())){fresh.add(e.getName());var c=FreezeSourceTargetDelta.read(jar,e.getName().replace(".class",""));need(c.fields.isEmpty(),"stateless relation helper");for(var m:c.methods)for(var n:m.instructions){need(n.getOpcode()!=MONITORENTER,"no new lock order");if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!t.desc.contains("Thread")&&!t.desc.contains("Executor")&&!t.desc.equals(P+"ClientSession")&&!t.desc.equals(P+"GameHub"),"no game fixtures or workers");if(n instanceof MethodInsnNode call)need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!Set.of("takePlayerDamage","applyDamage","enqueueBattle","setChargeCount","setProperty").contains(call.name),"no new HP lane/mutation/persistence");}}need(fresh.equals(Set.of(N+".class")),"one stateless helper only");System.out.println("PASS independent cube relation inverse: "+count+" original methods; reused exact original Binding.source identity and self/alliance adapters, original queued HP/cost/RNG/clocks/output unchanged");
 }}
}
